from __future__ import annotations

import sys
from collections import deque


class _Dinic:
    """Small integer Dinic max-flow implementation."""

    def __init__(self):
        self.ad = []
        self.level = []
        self.it = []

    def add_node(self):
        self.ad.append([])
        return len(self.ad) - 1

    def add_edge(self, u, v, c):
        # forward edge: [to, residual capacity, index of reverse edge]
        self.ad[u].append([v, c, len(self.ad[v])])
        # reverse edge
        self.ad[v].append([u, 0, len(self.ad[u]) - 1])
        return len(self.ad[u]) - 1

    def _bfs(self, s, t):
        ad = self.ad
        level = [-1] * len(ad)
        level[s] = 0
        q = deque([s])

        while q:
            v = q.popleft()
            if v == t:
                continue
            nxt_level = level[v] + 1
            for e in ad[v]:
                if e[1] > 0 and level[e[0]] == -1:
                    level[e[0]] = nxt_level
                    q.append(e[0])

        self.level = level
        return level[t] != -1

    def _dfs(self, v, t, f):
        if v == t:
            return f

        ad = self.ad
        level = self.level
        it = self.it

        while it[v] < len(ad[v]):
            e = ad[v][it[v]]
            if e[1] > 0 and level[e[0]] == level[v] + 1:
                pushed = self._dfs(e[0], t, f if f < e[1] else e[1])
                if pushed:
                    e[1] -= pushed
                    ad[e[0]][e[2]][1] += pushed
                    return pushed
            it[v] += 1

        return 0

    def max_flow(self, s, t, limit):
        flow = 0
        while flow < limit and self._bfs(s, t):
            self.it = [0] * len(self.ad)
            while flow < limit:
                pushed = self._dfs(s, t, limit - flow)
                if pushed == 0:
                    break
                flow += pushed
        return flow


def assign_shifts(
    shifts: list[tuple[str, int, int, int]],
    engineers: dict[str, dict],
) -> dict[str, list[str]] | None:
    sys.setrecursionlimit(1_000_000)

    shift_info = {}
    result = {}
    total_need = 0
    senior_need = 0

    for shift_id, day, headcount, min_seniors in shifts:
        if headcount < 0 or min_seniors < 0 or min_seniors > headcount:
            return None
        shift_info[shift_id] = (day, headcount, min_seniors)
        result[shift_id] = []
        total_need += headcount
        senior_need += min_seniors

    if total_need == 0:
        return result

    # Cheap necessary capacity checks.
    if total_need > sum(info["max_shifts"] for info in engineers.values()):
        return None
    if senior_need > sum(
        info["max_shifts"] for info in engineers.values() if info["senior"]
    ):
        return None

    dinic = _Dinic()
    source = dinic.add_node()
    sink = dinic.add_node()

    # Layer 1: engineer nodes, with total shift capacity.
    engineer_node = {}
    for name, info in engineers.items():
        node = dinic.add_node()
        engineer_node[name] = node
        cap = info["max_shifts"]
        if cap > total_need:
            cap = total_need
        if cap > 0:
            dinic.add_edge(source, node, cap)

    # Shift slot nodes:
    #   senior slots can only be filled by seniors;
    #   open slots can be filled by anyone.
    senior_slot = {}
    open_slot = {}

    for shift_id, day, headcount, min_seniors in shifts:
        if headcount == 0:
            continue

        if min_seniors > 0:
            node = dinic.add_node()
            senior_slot[shift_id] = node
            dinic.add_edge(node, sink, min_seniors)

        open_count = headcount - min_seniors
        if open_count > 0:
            node = dinic.add_node()
            open_slot[shift_id] = node
            dinic.add_edge(node, sink, open_count)

    # Layer 2: engineer/day nodes, capacity 1, enforcing
    # "at most one shift on a given day".
    day_node = {}
    assignment_edges = []

    for name, info in engineers.items():
        if info["max_shifts"] <= 0:
            continue

        eng_node = engineer_node[name]
        is_senior = info["senior"]

        for shift_id in info["available"]:
            sh = shift_info.get(shift_id)
            if sh is None:
                continue

            day, headcount, min_seniors = sh
            if headcount == 0:
                continue

            key = (name, day)
            d_node = day_node.get(key)
            if d_node is None:
                d_node = dinic.add_node()
                day_node[key] = d_node
                dinic.add_edge(eng_node, d_node, 1)

            if is_senior:
                slot = senior_slot.get(shift_id)
                if slot is not None:
                    idx = dinic.add_edge(d_node, slot, 1)
                    assignment_edges.append((d_node, idx, name, shift_id))

            slot = open_slot.get(shift_id)
            if slot is not None:
                idx = dinic.add_edge(d_node, slot, 1)
                assignment_edges.append((d_node, idx, name, shift_id))

    if dinic.max_flow(source, sink, total_need) != total_need:
        return None

    # All assignment edges have capacity 1. If residual capacity is 0,
    # that engineer-shift assignment was used.
    for d_node, idx, name, shift_id in assignment_edges:
        if dinic.ad[d_node][idx][1] == 0:
            result[shift_id].append(name)

    for names in result.values():
        names.sort()

    return result
